    hotel_cap = float(allowances.get("hotel_per_night", 0.0))
    rates = policy.get("company_rates_usd_per_unit", {}).get(month, {})

    def to_usd(amount, currency):
        if currency == "USD" or currency is None or currency == "":
            return float(amount)
        if currency not in rates:
            raise KeyError("no company rate for " + str(currency) + " in " + month)
        return float(amount) * float(rates[currency])

    meals_by_day = {}
    hotel_by_day = {}
