            # each hotel receipt is one night, capped individually
            hotel_by_day[date] = hotel_by_day.get(date, 0.0) + min(usd, hotel_cap)
        elif category == "taxi":
            if usd > 40.0 and note.strip() == "":
                continue
            other += usd
        else:
            other += usd

    total = other
    for d in meals_by_day:
        total += min(meals_by_day[d], meal_cap)
    for d in hotel_by_day:
